var e=`userProfile`;chrome.runtime.onInstalled.addListener(async t=>{t.reason===`install`&&((await chrome.storage.local.get(e))[e]||chrome.tabs.create({url:chrome.runtime.getURL(`onboarding.html`)}))}),chrome.runtime.onMessage.addListener((t,n,r)=>{switch(t.type){case`GET_PROFILE`:return chrome.storage.local.get(e,t=>r({profile:t[e]??null})),!0;case`SAVE_PROFILE`:return chrome.storage.local.set({[e]:t.payload},()=>r({ok:!0})),!0;case`RESET_PROFILE`:return chrome.storage.local.remove(e,()=>r({ok:!0})),!0}});